from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from pathlib import Path
out=Path(__file__).resolve().parent/'PROJECT_EXECUTION_GUIDE.pdf'
navy=colors.HexColor('#0B1422'); blue=colors.HexColor('#477BFF'); cyan=colors.HexColor('#41D8E8'); muted=colors.HexColor('#52627A')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=29,leading=34,textColor=navy,spaceAfter=12,alignment=TA_CENTER))
styles.add(ParagraphStyle(name='CoverSub',parent=styles['Normal'],fontSize=12,leading=18,textColor=muted,alignment=TA_CENTER,spaceAfter=20))
styles.add(ParagraphStyle(name='H1x',parent=styles['Heading1'],fontName='Helvetica-Bold',fontSize=18,leading=22,textColor=navy,spaceBefore=8,spaceAfter=10))
styles.add(ParagraphStyle(name='H2x',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=12,leading=15,textColor=blue,spaceBefore=8,spaceAfter=5))
styles.add(ParagraphStyle(name='Bodyx',parent=styles['BodyText'],fontSize=9,leading=13,textColor=colors.HexColor('#253247'),spaceAfter=6))
styles.add(ParagraphStyle(name='CodeX',parent=styles['Code'],fontName='Courier',fontSize=8,leading=11,textColor=colors.HexColor('#E9F1FF'),backColor=navy,borderPadding=8,spaceBefore=4,spaceAfter=9))
styles.add(ParagraphStyle(name='Smallx',parent=styles['BodyText'],fontSize=8,leading=11,textColor=muted,spaceAfter=5))
def P(t,style='Bodyx'): return Paragraph(t,styles[style])
def code(t): return P(t.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('\n','<br/>'),'CodeX')
def footer(canvas,doc):
    canvas.saveState(); w,h=A4; canvas.setStrokeColor(colors.HexColor('#DCE4EF')); canvas.line(18*mm,15*mm,w-18*mm,15*mm); canvas.setFont('Helvetica',8); canvas.setFillColor(muted); canvas.drawString(18*mm,10*mm,'FreightIQ · Local execution guide · fictional synthetic data'); canvas.drawRightString(w-18*mm,10*mm,f'Page {doc.page}'); canvas.restoreState()
doc=SimpleDocTemplate(str(out),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=17*mm,bottomMargin=21*mm,title='FreightIQ Project Execution Guide',author='FreightIQ Project')
story=[]
story += [Spacer(1,26*mm),P('Freight<span color="#41D8E8">IQ</span>','CoverTitle'),P('PROJECT EXECUTION GUIDE','CoverSub'),Spacer(1,5*mm),P('Freight Invoice Audit · Investigation · Credit Control · Reconciliation','CoverSub'),Spacer(1,15*mm)]
t=Table([[P('<b>VALIDATE</b><br/>Compare invoice charges against contract rates and shipment data.','Bodyx'),P('<b>INVESTIGATE</b><br/>Preserve analyst findings, manager decisions and carrier responses.','Bodyx'),P('<b>RECONCILE</b><br/>Verify actual credit notes and track applied and remaining balances.','Bodyx')]],colWidths=[55*mm,55*mm,55*mm])
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#EEF4FB')),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#CFDAE8')),('INNERGRID',(0,0),(-1,-1),.5,colors.HexColor('#CFDAE8')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),12)])); story.append(t)
story += [Spacer(1,20*mm),P('This guide documents the implemented local-development workflow. Demo companies, products, invoice references and transactions generated by FreightIQ are fictional synthetic data.','CoverSub'),PageBreak()]
story += [P('1. Project overview','H1x'),P('FreightIQ is a Django web application using SQLite, Django authentication, HTML/CSS/JavaScript and Bootstrap 5. The application connects registration approval, shipment operations, invoice validation, investigation, manager review, carrier response, credit-note verification, credit application and reconciliation. Core calculations and state transitions are implemented in reusable service modules.','Bodyx'),P('2. Install Python on Windows','H1x'),P('Install Python 3.11 or 3.12 from the official Python distribution. During setup, enable the option to add Python to PATH. Open PowerShell and confirm the interpreter is available:','Bodyx'),code('py --version\npython --version'),P('3. Create a virtual environment and install dependencies','H1x'),code('cd path\\to\\freightiq\npy -3.12 -m venv .venv\n.\\.venv\\Scripts\\Activate.ps1\npython -m pip install --upgrade pip\npip install -r requirements.txt'),P('If PowerShell blocks activation, run this for the current terminal only, then activate again:','Bodyx'),code('Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass\n.\\.venv\\Scripts\\Activate.ps1'),P('4. Create database tables and the initial administrator','H1x'),code('python manage.py makemigrations audit\npython manage.py migrate\npython manage.py createsuperuser'),P('Choose a strong administrator username and password. The System Administrator is not a public registration role. Use these credentials on the normal FreightIQ login page; the superuser is routed to the administrator workspace.','Bodyx'),P('5. Generate the demonstration data','H1x'),code('python manage.py generate_freight_data --seed 20261022 --carriers 12 --shipments 100 --invoices 70\npython manage.py validate_freight_data\npython manage.py export_freight_data --directory data/exports'),P('The compact dataset is intended for initial checks. The full target can be generated with 100 carriers, 20,000 shipments and 15,000 invoices; this takes longer and consumes more disk space. A fixed seed makes logical records and anomaly selection reproducible.','Bodyx'),PageBreak()]
story += [P('6. Start FreightIQ','H1x'),code('python manage.py runserver'),P('Open http://127.0.0.1:8000/. Django Admin is available at http://127.0.0.1:8000/admin/ for authorized administrators. Stop the development server with Ctrl+C.','Bodyx'),P('7. Registration and administrator approval','H1x'),P('From the login screen, choose Request access. Enter full name, username, password, confirmation, requested role and organization where required. The role responsibilities update immediately when the role selector changes. Applicants do not enter a profile description and cannot request System Administrator access.','Bodyx'),P('Sign in as the superuser and open User approvals. Review the applicant and standard responsibilities. Approve the application only when the organization matches the existing master record; carrier applicants are mapped to a carrier, and supplier applicants are mapped to a supplier. Rejection requires a reason. Decisions are recorded in audit history.','Bodyx'),P('8. Log in with each approved role','H1x'),P('<b>Planner:</b> open Shipments, create a shipment and record carrier, supplier, cargo, lane, service, weight, dimensions and delivery details.','Bodyx'),P('<b>Supplier:</b> submit an invoice, select shipment and counterparties, enter billed base/fuel/accessorial amounts, declared total and supporting evidence.','Bodyx'),P('<b>Logistics Analyst:</b> open an exception from the invoice detail page, record findings/root cause/evidence, recommend a credit or no credit and submit to the manager.','Bodyx'),P('<b>Operations Manager:</b> review the case, approve, reject with a reason or return with comments. Each action creates a separate decision record.','Bodyx'),P('<b>Carrier / Warehouse Operator:</b> open a manager-approved case associated with the mapped carrier, then accept, dispute with an explanation or counteroffer.','Bodyx'),P('<b>Finance:</b> open Finance & credits, record the actual note received after carrier acceptance, verify it, apply a verified credit within its remaining balance and reconcile.','Bodyx'),P('9. Invoice calculation and investigation','H1x'),P('Expected base freight uses the valid carrier/lane/service rate card and applicable weight tier, applying the minimum charge. Billable weight is the greater of actual and dimensional weight. Fuel surcharge is calculated from base freight and the contracted percentage. The discrepancy formula is billed total minus expected total. A positive discrepancy indicates a potential overcharge; a negative discrepancy is an undercharge, not a credit owed.','Bodyx'),P('The invoice case workspace combines invoice, shipment, product, carrier, supplier, lane, weights, dimensions, rate card, financial comparison, validation findings, reviews, decisions, carrier responses, credit notes, reconciliation records and audit events. Role-specific actions appear only at eligible workflow stages.','Bodyx'),PageBreak()]
story += [P('10. Credit-note verification and reconciliation','H1x'),P('A manager approval is not proof that a credit note was issued. Finance records the actual amount, currency, date and document reference. Verification compares the actual amount with the approved and carrier-agreed amount and checks currency. A mismatched or unverified note is not eligible for normal application.','Bodyx'),P('Applications are separate persistent records and create invoice adjustments. Partial applications are allowed. A verified credit can be applied to an eligible invoice for the same carrier and currency, including the original invoice. Application cannot exceed the verified note balance and each application requires a unique reference. Reversals require a reason and preserve the original application. Reconciliation compares approved, agreed, issued, verified, applied, remaining and difference amounts from stored records.','Bodyx'),P('11. CSV import, exports and validation','H1x'),code('python manage.py import_freight_csv --directory data\npython manage.py export_freight_data --directory data/exports\npython manage.py validate_freight_data'),P('The importer loads optional master CSVs from data/master/ first, then transactions/shipments.csv and transactions/invoices.csv. Shipment, supplier and carrier references must resolve to master records. The included compact fictional fixture contains 12 shipments and 12 invoices. Existing invoice numbers/codes are skipped to avoid duplicate imports. Exports include master/transaction CSV and JSON files; ground-truth labels are separate under data/ground_truth/.','Bodyx'),P('12. Logout and session protection','H1x'),P('Use the Logout control, which submits a CSRF-protected POST request. Django logout invalidates the session and redirects to the login page. Protected views require authentication and approved profile status. Authenticated responses set no-store cache headers; refreshing a protected page after logout should redirect to login.','Bodyx'),P('13. Run checks and tests','H1x'),code('python manage.py check\npython manage.py test\npython manage.py validate_freight_data'),P('Review the output rather than assuming a pass. The automated suite covers core calculations, exception idempotency, selected authorization rules, manager reason requirements, carrier isolation and logout. The complete master prompt includes additional edge cases that should be tested manually before production use.','Bodyx'),P('14. Common troubleshooting','H1x'),P('<b>ModuleNotFoundError: django</b> — activate `.venv` and run `pip install -r requirements.txt`.','Bodyx'),P('<b>No such table</b> — run `python manage.py makemigrations audit` followed by `python manage.py migrate`.','Bodyx'),P('<b>Rate card not found</b> — generate master data and confirm that carrier, lane, service and shipment date match a valid rate card.','Bodyx'),P('<b>Registration approval blocked</b> — use an organization name matching an existing supplier/carrier master record.','Bodyx'),P('<b>Credit cannot be applied</b> — verify carrier acceptance, manager approval, note currency and verification status; confirm requested amount does not exceed remaining balance.','Bodyx'),P('<b>Resetting demo data</b> — back up `db.sqlite3` first. `--reset` targets only records marked `is_synthetic=True`; never remove the database file as a reset shortcut in a shared environment.','Bodyx'),P('15. Production-readiness note','H1x'),P('This is a local-development baseline. Before production deployment, externalize the secret key, set DEBUG=False, configure HTTPS and secure cookies, use a production database and static/media storage, add structured monitoring, review file-upload security, test every acceptance criterion, and perform a security review.','Bodyx')]
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(out, out.stat().st_size)
